import { randomUUID } from 'node:crypto'
import type { H3Event } from 'h3'
import type { Note, SharedNote } from '#shared/types/note'

const SESSION_COOKIE = 'sid'

const notesByUser = new Map<string, Note[]>([
  ['ada', [
    { id: 'n1', title: 'Buy milk', pinned: false, archived: false, createdAt: '2026-01-15T09:00:00.000Z' },
    { id: 'n2', title: 'Call Bob', pinned: false, archived: false, createdAt: '2026-01-14T09:00:00.000Z' },
  ]],
  ['bob', [{ id: 'n3', title: "Bob's secret", pinned: false, archived: false, createdAt: '2026-01-10T09:00:00.000Z' }]],
])

let nextNoteId = 4

const sessions = new Map<string, string>()

/** The user's most recent delete, kept until it is undone, the notes change again or the user signs out. */
const lastDeletedByUser = new Map<string, { note: Note; index: number }>()

/** Any other change to a user's notes makes the last delete no longer undoable. */
function forgetDeleted(name: string): void {
  lastDeletedByUser.delete(userKey(name))
}

export function lastDeleted(name: string): Note | null {
  return lastDeletedByUser.get(userKey(name))?.note ?? null
}

/** Puts the last deleted note back at its old place, unchanged. */
export function undoDelete(name: string): Note | null {
  const key = userKey(name)
  const entry = lastDeletedByUser.get(key)
  if (!entry) return null
  lastDeletedByUser.delete(key)
  const notes = notesByUser.get(key) ?? []
  notes.splice(Math.min(entry.index, notes.length), 0, entry.note)
  notesByUser.set(key, notes)
  return entry.note
}

function userKey(name: string): string {
  return name.toLowerCase()
}

function userNotes(name: string): Note[] {
  return notesByUser.get(userKey(name)) ?? []
}

/** Notes that are not archived: pinned first; otherwise newest first, as stored. */
export function listNotes(name: string): Note[] {
  const notes = userNotes(name).filter((note) => !note.archived)
  return [...notes.filter((note) => note.pinned), ...notes.filter((note) => !note.pinned)]
}

/** Every note the user owns, archived ones included, in the list page's order: pinned first, then newest first, as stored. */
export function listOwnNotes(name: string): Note[] {
  const notes = userNotes(name)
  return [...notes.filter((note) => note.pinned), ...notes.filter((note) => !note.pinned)]
}

/** Archived notes, newest first, as stored. */
export function listArchivedNotes(name: string): Note[] {
  return userNotes(name).filter((note) => note.archived)
}

/** Archived notes count too: their titles stay taken. `exceptId` leaves one note out of the check, so a note never clashes with itself when renamed. */
export function noteExists(name: string, title: string, exceptId?: string): boolean {
  const normalized = title.trim().toLowerCase()
  return userNotes(name).some((note) => note.id !== exceptId && note.title.trim().toLowerCase() === normalized)
}

/** Adds per user within any `ADD_WINDOW_MS`; only notes actually added count. */
export const ADD_LIMIT = 10
const ADD_WINDOW_MS = 60_000
const addTimesByUser = new Map<string, number[]>()

function recentAdds(name: string, now = Date.now()): number[] {
  const key = userKey(name)
  const times = (addTimesByUser.get(key) ?? []).filter((time) => now - time < ADD_WINDOW_MS)
  addTimesByUser.set(key, times)
  return times
}

/** Seconds until the user may add another note; 0 when they may add one now. */
export function addRetryAfter(name: string): number {
  const now = Date.now()
  const times = recentAdds(name, now)
  if (times.length < ADD_LIMIT) return 0
  return Math.max(1, Math.ceil((times[times.length - ADD_LIMIT]! + ADD_WINDOW_MS - now) / 1000))
}

export function addNote(name: string, title: string): Note {
  const key = userKey(name)
  recentAdds(name).push(Date.now())
  const notes = notesByUser.get(key) ?? []
  const note: Note = { id: `n${nextNoteId++}`, title, pinned: false, archived: false, createdAt: new Date().toISOString() }
  notes.unshift(note)
  notesByUser.set(key, notes)
  forgetDeleted(name)
  return note
}

export function deleteNote(name: string, id: string): boolean {
  const notes = notesByUser.get(userKey(name))
  const index = notes?.findIndex((note) => note.id === id) ?? -1
  if (!notes || index === -1) return false
  const [note] = notes.splice(index, 1)
  lastDeletedByUser.set(userKey(name), { note: note!, index })
  return true
}

/** Deletes the listed notes that are not archived. A bulk delete cannot be undone, so it also forgets the last delete. */
export function deleteNotes(name: string, ids: string[]): number {
  const key = userKey(name)
  const wanted = new Set(ids)
  const notes = notesByUser.get(key) ?? []
  const kept = notes.filter((note) => note.archived || !wanted.has(note.id))
  const removed = notes.length - kept.length
  if (removed === 0) return 0
  for (const note of notes) if (!kept.includes(note)) sharesByNote.delete(note.id)
  notesByUser.set(key, kept)
  forgetDeleted(name)
  return removed
}

/** Archives the listed notes that are not archived yet. */
export function archiveNotes(name: string, ids: string[]): number {
  const wanted = new Set(ids)
  const notes = userNotes(name).filter((note) => !note.archived && wanted.has(note.id))
  for (const note of notes) note.archived = true
  if (notes.length) forgetDeleted(name)
  return notes.length
}

export function findNote(name: string, id: string): Note | null {
  return userNotes(name).find((note) => note.id === id) ?? null
}

/** Changes only the title; position, pin and creation date stay as they are. */
export function renameNote(name: string, id: string, title: string): Note | null {
  const note = findNote(name, id)
  if (!note) return null
  note.title = title
  forgetDeleted(name)
  return note
}

export function setPinned(name: string, id: string, pinned: boolean): Note | null {
  const note = userNotes(name).find((note) => note.id === id)
  if (!note) return null
  note.pinned = pinned
  forgetDeleted(name)
  return note
}

/** Only flips the flag, so a restored note keeps its title, pin, date and position. */
export function setArchived(name: string, id: string, archived: boolean): Note | null {
  const note = findNote(name, id)
  if (!note) return null
  note.archived = archived
  forgetDeleted(name)
  return note
}

/** Note id -> names it is shared with, as the owner typed them (unique ignoring case). */
const sharesByNote = new Map<string, string[]>()

/** Last name each user signed in with, shown as the owner of notes they share. */
const displayNames = new Map<string, string>()

export function sharedWith(id: string): string[] {
  return sharesByNote.get(id) ?? []
}

/** Gives `recipient` read access to one of `name`'s notes; sharing twice changes nothing. */
export function shareNote(name: string, id: string, recipient: string): boolean {
  if (!findNote(name, id)) return false
  const names = sharedWith(id)
  if (!names.some((other) => userKey(other) === userKey(recipient))) sharesByNote.set(id, [...names, recipient])
  return true
}

export function unshareNote(name: string, id: string, recipient: string): boolean {
  if (!findNote(name, id)) return false
  const names = sharedWith(id).filter((other) => userKey(other) !== userKey(recipient))
  if (names.length) sharesByNote.set(id, names)
  else sharesByNote.delete(id)
  return true
}

/** Notes others share with `name` that are still on their owner's list (not archived or deleted), with their current title. */
export function listSharedWith(name: string): SharedNote[] {
  const key = userKey(name)
  const shared: SharedNote[] = []
  for (const owner of notesByUser.keys()) {
    if (owner === key) continue
    for (const note of listNotes(owner)) {
      if (sharedWith(note.id).some((other) => userKey(other) === key)) {
        shared.push({ id: note.id, title: note.title, owner: displayNames.get(owner) ?? owner })
      }
    }
  }
  return shared
}

export function sameUser(a: string, b: string): boolean {
  return userKey(a) === userKey(b)
}

export function signIn(event: H3Event, name: string): void {
  displayNames.set(userKey(name), name)
  const id = randomUUID()
  sessions.set(id, name)
  setCookie(event, SESSION_COOKIE, id, { httpOnly: true, sameSite: 'lax', path: '/' })
}

export function signOut(event: H3Event): void {
  const id = getCookie(event, SESSION_COOKIE)
  const name = id ? sessions.get(id) : undefined
  if (name) forgetDeleted(name)
  if (id) sessions.delete(id)
  deleteCookie(event, SESSION_COOKIE, { httpOnly: true, sameSite: 'lax', path: '/' })
}

export function currentUser(event: H3Event): string | null {
  const id = getCookie(event, SESSION_COOKIE)
  return id ? sessions.get(id) ?? null : null
}

/** Plain HTML form posts get redirects; JS (JSON) requests get status codes. */
export function isFormPost(event: H3Event): boolean {
  return (getRequestHeader(event, 'content-type') ?? '').includes('application/x-www-form-urlencoded')
}

/** Every user who has signed in or owns notes, with their note count (archived included), in name order. */
export function listUsers(): { name: string; notes: number }[] {
  const keys = new Set([...displayNames.keys(), ...notesByUser.keys()])
  return [...keys]
    .sort()
    .map((key) => ({ name: displayNames.get(key) ?? key, notes: notesByUser.get(key)?.length ?? 0 }))
}

/** Removes every trace of the user: notes (archived included) and their shares, undo, add limit, display name and all sessions. Shares others made to the user stay with their owners. */
export function deleteAccount(name: string): void {
  const key = userKey(name)
  for (const note of notesByUser.get(key) ?? []) sharesByNote.delete(note.id)
  notesByUser.delete(key)
  lastDeletedByUser.delete(key)
  addTimesByUser.delete(key)
  displayNames.delete(key)
  for (const [id, other] of sessions) if (userKey(other) === key) sessions.delete(id)
}
export interface Note {
  id: string
  title: string
  pinned: boolean
  /** Archived notes are read-only and leave the list page until restored. */
  archived: boolean
  /** ISO 8601 UTC timestamp, set by the server when the note is created. */
  createdAt: string
  /** Names the note is shared with; only sent to its owner. */
  sharedWith?: string[]
}

/** A note another user shares: only what the recipient may see. */
export interface SharedNote {
  id: string
  title: string
  owner: string
}

export interface NotesResponse {
  name: string | null
  notes: Note[]
  /** Title of the most recent delete that can still be undone (list page only). */
  deletedTitle?: string | null
  /** Notes other users share with this user (list page only). */
  shared?: SharedNote[]
}

export const RATE_LIMIT_ERROR = 'Too many notes, try again in a minute'

export const ARCHIVED_ERROR = 'Archived notes are read-only'

export const SHARE_SELF_ERROR = 'You cannot share with yourself'
export const SHARE_NAME_ERROR = 'Name must be 2-20 letters'

export const NAME_PATTERN = /^[A-Za-z]{2,20}$/
export const NOTE_MAX_LENGTH = 60

/** Names are case-insensitive, so `Admin` is the same user as `admin`. */
export function isAdmin(name: string | null | undefined): boolean {
  return name?.toLowerCase() === 'admin'
}

/** One row of the admin page: a user and how many notes they own, archived ones included. */
export interface AdminUser {
  name: string
  notes: number
}

export interface AdminResponse {
  name: string | null
  /** Only filled in for the admin. */
  allowed: boolean
  users: AdminUser[]
}
<script setup lang="ts">
import { NOTE_MAX_LENGTH, isAdmin, RATE_LIMIT_ERROR, SHARE_NAME_ERROR, SHARE_SELF_ERROR, type Note, type NotesResponse } from '#shared/types/note'

const route = useRoute()
const t = useT()
const router = useRouter()

const { data, refresh } = await useFetch<NotesResponse>('/api/notes', {
  key: 'notes',
  default: () => ({ name: null, notes: [] }),
})

if (!data.value.name) {
  await navigateTo('/login', { replace: true })
}

const notes = computed(() => data.value.notes)
// Notes other users share with this user: read-only, and kept apart from the user's own notes.
const sharedNotes = computed(() => data.value.shared ?? [])

// Seeded from ?q= so the search form also filters without JavaScript.
const search = ref(typeof route.query.q === 'string' ? route.query.q : '')
// Keep the input in step with the URL on client-side navigation (links, back/forward).
watch(() => route.query.q, (q) => {
  search.value = typeof q === 'string' ? q : ''
})
// Seeded from ?edit= / ?editError= so editing also works without JavaScript.
const editingId = ref(typeof route.query.edit === 'string' ? route.query.edit : null)
// Seeded from ?share= / ?shareError= so a failed share shows its error without JavaScript.
const shareErrorId = typeof route.query.share === 'string' ? route.query.share : null

const urlSearch = computed(() => (typeof route.query.q === 'string' ? route.query.q.trim().toLowerCase() : ''))

function matches(note: Note, query: string) {
  return note.title.toLowerCase().includes(query)
}

/** Notes the URL search (`?q=`) selects, before paging. */
const filteredNotes = computed(() => (urlSearch.value ? notes.value.filter((note) => matches(note, urlSearch.value)) : notes.value))

// Paging lives in the URL (`?limit=`) so `Load more` also works without JavaScript.
const PAGE_SIZE = 5
const limit = computed(() => {
  const raw = Number(route.query.limit)
  let value = Number.isInteger(raw) && raw > PAGE_SIZE ? raw : PAGE_SIZE
  // A note opened for editing (e.g. after a failed edit without JavaScript) is always listed.
  const editIndex = filteredNotes.value.findIndex((note) => note.id === editingId.value)
  if (editIndex >= value) value = Math.ceil((editIndex + 1) / PAGE_SIZE) * PAGE_SIZE
  // Likewise a note whose share failed, so its error is visible.
  const shareIndex = shareErrorId ? filteredNotes.value.findIndex((note) => note.id === shareErrorId) : -1
  if (shareIndex >= value) value = Math.ceil((shareIndex + 1) / PAGE_SIZE) * PAGE_SIZE
  return value
})
const listedNotes = computed(() => filteredNotes.value.slice(0, limit.value))
const hasMore = computed(() => filteredNotes.value.length > listedNotes.value.length)

// Typing in Search with JavaScript filters the notes currently listed.
const visibleNotes = computed(() => {
  const query = search.value.trim().toLowerCase()
  return query && query !== urlSearch.value ? listedNotes.value.filter((note) => matches(note, query)) : listedNotes.value
})

/** The current search as URL query, so navigation keeps `q` (and `limit` when asked). */
function filterQuery(next: { q?: string; limit?: number } = {}) {
  const q = (next.q ?? search.value).trim()
  const l = next.limit ?? PAGE_SIZE
  return { ...(q ? { q } : {}), ...(l > PAGE_SIZE ? { limit: String(l) } : {}) }
}

const loadMoreLink = computed(() => ({
  path: '/notes',
  query: filterQuery({ q: urlSearch.value ? String(route.query.q) : '', limit: limit.value + PAGE_SIZE }),
}))

function submitSearch() {
  router.replace({ query: filterQuery() })
}

const messages = computed<Record<string, string>>(() => ({
  duplicate: t('You already have a note with this title'),
  invalid: `Note must be 1–${NOTE_MAX_LENGTH} characters`,
  'too-long': `Use at most ${NOTE_MAX_LENGTH} characters`,
  'rate-limited': RATE_LIMIT_ERROR,
}))

const shareMessages: Record<string, string> = {
  self: SHARE_SELF_ERROR,
  invalid: SHARE_NAME_ERROR,
}

/** Error codes without a message of their own show the generic one. */
function knownCode(code: string | undefined) {
  return code && code in messages.value ? code : 'invalid'
}

// Codes, not texts, so a shown error follows a language switch.
const errorCode = ref(String(route.query.error ?? ''))
const errorMessage = computed(() => messages.value[errorCode.value] ?? '')
const newTitle = ref('')
const submitting = ref(false)
const deleting = ref<string | null>(null)
const pinning = ref<string | null>(null)
const archiving = ref<string | null>(null)
const undoing = ref(false)

const editTitle = ref(notes.value.find((note) => note.id === editingId.value)?.title ?? '')
const editErrorCode = ref(editingId.value ? String(route.query.editError ?? '') : '')
const editError = computed(() => messages.value[editErrorCode.value] ?? '')
const saving = ref(false)

/** `keep` is the number of notes to keep listed, read before the edit closes. */
function clearErrorQuery(keep = limit.value) {
  if (route.query.error || route.query.edit || route.query.editError || route.query.share || route.query.shareError) {
    router.replace({ query: filterQuery({ limit: keep }) })
  }
}

function startEdit(note: Note) {
  editingId.value = note.id
  editTitle.value = note.title
  editErrorCode.value = ''
  nextTick(() => document.getElementById(`edit-${note.id}`)?.focus())
}

function cancelEdit() {
  const keep = limit.value
  editingId.value = null
  editErrorCode.value = ''
  clearErrorQuery(keep)
}

async function saveEdit(note: Note) {
  if (saving.value) return
  saving.value = true
  try {
    await $fetch(`/api/notes/${note.id}/edit`, { method: 'POST', body: { title: editTitle.value } })
    const keep = limit.value
    editingId.value = null
    editErrorCode.value = ''
    clearErrorQuery(keep)
    await refresh()
  } catch (error) {
    const { statusCode: status, data: body } = error as { statusCode?: number; data?: { data?: { code?: string } } }
    if (status === 401) return navigateTo('/login')
    if (status === 404 || body?.data?.code === 'archived') {
      editingId.value = null
      await refresh()
    } else if (status === 409) editErrorCode.value = 'duplicate'
    else editErrorCode.value = knownCode(body?.data?.code)
  } finally {
    saving.value = false
  }
}

// Sharing: one name input and one error per note, keyed by note id.
const shareNames = ref<Record<string, string>>({})
const shareErrors = ref<Record<string, string>>(
  shareErrorId && shareMessages[String(route.query.shareError)] ? { [shareErrorId]: shareMessages[String(route.query.shareError)]! } : {},
)
const sharing = ref<string | null>(null)

async function shareNote(note: Note) {
  if (sharing.value) return
  sharing.value = note.id
  try {
    await $fetch(`/api/notes/${note.id}/share`, { method: 'POST', body: { name: shareNames.value[note.id] ?? '' } })
    shareNames.value = { ...shareNames.value, [note.id]: '' }
    shareErrors.value = { ...shareErrors.value, [note.id]: '' }
    clearErrorQuery()
  } catch (error) {
    const { statusCode: status, data: body } = error as { statusCode?: number; data?: { data?: { code?: string } } }
    if (status === 401) return navigateTo('/login')
    shareErrors.value = { ...shareErrors.value, [note.id]: shareMessages[body?.data?.code ?? ''] ?? '' }
  } finally {
    sharing.value = null
  }
  await refresh()
}

async function unshareNote(note: Note, name: string) {
  if (sharing.value) return
  sharing.value = note.id
  try {
    await $fetch(`/api/notes/${note.id}/unshare`, { method: 'POST', body: { name } })
  } catch (error) {
    if ((error as { statusCode?: number }).statusCode === 401) return navigateTo('/login')
  } finally {
    sharing.value = null
  }
  await refresh()
}

/** The note being added, shown first in the list until the server has answered. */
const pendingNote = ref<Note | null>(null)

async function addNote() {
  // Synchronous guard so a quick double click only sends one request.
  if (submitting.value) return
  submitting.value = true
  const title = newTitle.value
  pendingNote.value = {
    id: 'pending',
    title: title.trim(),
    pinned: false,
    archived: false,
    createdAt: new Date().toISOString(),
  }
  newTitle.value = ''
  try {
    const created = await $fetch<Note>('/api/notes', { method: 'POST', body: { title } })
    // Accepted: list the server's note in place of the pending one, then sync with the server.
    data.value = { ...data.value, notes: [created, ...data.value.notes.filter((note) => note.id !== created.id)] }
    pendingNote.value = null
    errorCode.value = ''
    clearErrorQuery()
    await refresh()
  } catch (error) {
    pendingNote.value = null
    // Give the rejected input back unless the user has started typing another note.
    if (!newTitle.value) newTitle.value = title
    const { statusCode: status, data: body } = error as { statusCode?: number; data?: { data?: { code?: string } } }
    if (status === 401) return navigateTo('/login')
    if (status === 409) errorCode.value = 'duplicate'
    else errorCode.value = knownCode(body?.data?.code)
  } finally {
    submitting.value = false
  }
}

async function deleteNote(note: Note) {
  if (deleting.value) return
  deleting.value = note.id
  try {
    await $fetch(`/api/notes/${note.id}/delete`, { method: 'POST', body: {} })
  } catch (error) {
    if ((error as { statusCode?: number }).statusCode === 401) return navigateTo('/login')
  } finally {
    deleting.value = null
  }
  await refresh()
}

async function undoDelete() {
  if (undoing.value) return
  undoing.value = true
  try {
    await $fetch('/api/notes/undo', { method: 'POST', body: {} })
  } catch (error) {
    if ((error as { statusCode?: number }).statusCode === 401) return navigateTo('/login')
  } finally {
    undoing.value = false
  }
  await refresh()
}

async function archiveNote(note: Note) {
  if (archiving.value) return
  archiving.value = note.id
  try {
    await $fetch(`/api/notes/${note.id}/archive`, { method: 'POST', body: {} })
    if (editingId.value === note.id) cancelEdit()
  } catch (error) {
    if ((error as { statusCode?: number }).statusCode === 401) return navigateTo('/login')
  } finally {
    archiving.value = null
  }
  await refresh()
}

// Bulk actions: the checkboxes belong to the `bulk` form, so they also post without JavaScript.
const selected = ref<string[]>([])
const bulking = ref(false)
// `Selected: <n>` only shows once JavaScript runs, since it cannot update without it.
const mounted = ref(false)
onMounted(() => {
  mounted.value = true
})
/** Checked notes that are still listed; hidden or removed notes do not count. */
const selectedIds = computed(() => visibleNotes.value.filter((note) => selected.value.includes(note.id)).map((note) => note.id))

async function bulkAction(action: 'delete' | 'archive') {
  const ids = selectedIds.value
  if (bulking.value || ids.length === 0) return
  bulking.value = true
  try {
    await $fetch('/api/notes/bulk', { method: 'POST', body: { action, ids } })
    if (editingId.value && ids.includes(editingId.value)) cancelEdit()
    selected.value = selected.value.filter((id) => !ids.includes(id))
  } catch (error) {
    if ((error as { statusCode?: number }).statusCode === 401) return navigateTo('/login')
  } finally {
    bulking.value = false
  }
  await refresh()
}

async function togglePin(note: Note) {
  if (pinning.value) return
  pinning.value = note.id
  try {
    await $fetch(`/api/notes/${note.id}/pin`, { method: 'POST', body: { pinned: !note.pinned } })
  } catch (error) {
    if ((error as { statusCode?: number }).statusCode === 401) return navigateTo('/login')
  } finally {
    pinning.value = null
  }
  await refresh()
}
</script>

<template>
  <main class="mx-auto max-w-xl px-4 py-12">
    <header class="flex items-start justify-between gap-4">
      <div>
        <h1 class="text-3xl font-bold tracking-tight text-slate-900">{{ t('Notes') }}</h1>
        <p class="mt-1 text-sm text-slate-600">{{ t('Signed in as') }} {{ data.name }}</p>
      </div>
      <div class="flex items-center gap-2">
        <LangSwitch />
        <form method="post" action="/api/logout">
          <button
            type="submit"
            class="rounded-lg px-3 py-1.5 text-sm font-medium text-slate-700 ring-1 ring-slate-300 hover:bg-slate-100"
          >
            {{ t('Sign out') }}
          </button>
        </form>
      </div>
    </header>

    <form method="post" action="/api/notes" class="mt-8 flex flex-col gap-2" @submit.prevent="addNote">
      <label for="new-title" class="text-sm font-medium text-slate-700">{{ t('Title') }}</label>
      <div class="flex gap-2">
        <input
          id="new-title"
          v-model="newTitle"
          name="title"
          type="text"
          required
          minlength="1"
          :maxlength="NOTE_MAX_LENGTH"
          autocomplete="off"
          class="flex-1 rounded-lg border border-slate-300 bg-white px-3 py-2 text-slate-900 shadow-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
        >
        <button
